import { useEffect, useState } from "react";
import { User, UserRole } from "@/lib/auth";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import {
  User as UserIcon,
  Shield,
  Upload,
  X,
  Loader2,
  CheckCircle2,
  Mail,
  Phone,
  Building2,
  Search as SearchIcon,
  Check,
  ChevronRight,
  LayoutDashboard,
  Calendar,
  Users,
  UserSquare,
  Car,
  Wallet,
  Settings,
  CreditCard,
  Target,
  MapPin,
  Star,
} from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

import { SYSTEM_ORG_ID } from "@/lib/constants";
import { PERMISSION_LABELS, getPermissionsByContext } from "@/lib/permissions";

type Props = {
  onOpenChange: (open: boolean) => void;
  onSave: (data: FormData) => void;
  initialData?: Partial<User>;
  isNew?: boolean;
  isLoading?: boolean;
};

export function UserForm({
  onOpenChange,
  onSave,
  initialData,
  isNew = true,
  isLoading = false,
}: Props) {
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [phoneNumber, setPhoneNumber] = useState("");
  const [role, setRole] = useState<UserRole>(UserRole.SYSTEM_ADMIN);
  const [profileImage, setProfileImage] = useState<File | null>(null);
  const [permissions, setPermissions] = useState<string[]>([]);
  const [preview, setPreview] = useState<string | null>(null);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [permSearch, setPermSearch] = useState("");
  const [expandedCategories, setExpandedCategories] = useState<string[]>([]);

  useEffect(() => {
    if (!initialData) return;
    setFullName(initialData.fullName || "");
    setEmail(initialData.email || "");
    setPhoneNumber(initialData.phoneNumber || "");
    setRole((initialData.role as UserRole) || UserRole.SYSTEM_ADMIN);
    if (
      initialData.profileImage &&
      typeof initialData.profileImage === "string"
    ) {
      setPreview(initialData.profileImage);
    }
    // Handle permissions if backend returns it as array
    if (initialData.permissions && Array.isArray(initialData.permissions)) {
      setPermissions(initialData.permissions);
    }
  }, [initialData]);

  useEffect(() => {
    if (!profileImage) return;
    const url = URL.createObjectURL(profileImage);
    setPreview(url);
    return () => URL.revokeObjectURL(url);
  }, [profileImage]);

  const validate = () => {
    const newErrors: Record<string, string> = {};
    if (!fullName.trim()) newErrors.fullName = "Full name is required";
    if (!email.trim()) newErrors.email = "Email is required";
    if (!phoneNumber.trim()) newErrors.phoneNumber = "Phone number is required";
    if (!role) newErrors.role = "Role is required";

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = () => {
    if (!validate()) {
      toast.error("Please fill in all required fields marked in red");
      return;
    }

    const formData = new FormData();
    formData.append("fullName", fullName);
    formData.append("email", email);
    formData.append("phoneNumber", phoneNumber);
    formData.append("role", role);
    formData.append("isStaffUser", "true");

    // Default orgId for system users
    if (role === UserRole.SYSTEM_SUPER_ADMIN || role === UserRole.SYSTEM_ADMIN) {
      formData.append("orgId", SYSTEM_ORG_ID);
    }

    if (profileImage) {
      formData.append("profileImage", profileImage);
    }

    // Add Permissions
    if (permissions.length > 0) {
      permissions.forEach(p => formData.append("permissions", p));
    }

    onSave(formData);
  };

  const togglePermission = (permission: string) => {
    setPermissions(prev =>
      prev.includes(permission)
        ? prev.filter(p => p !== permission)
        : [...prev, permission]
    );
  };

  const toggleCategory = (categoryPermissions: string[]) => {
    const allSelected = categoryPermissions.every(p => permissions.includes(p));
    if (allSelected) {
      setPermissions(prev => prev.filter(p => !categoryPermissions.includes(p)));
    } else {
      setPermissions(prev => {
        const newPerms = [...prev];
        categoryPermissions.forEach(p => {
          if (!newPerms.includes(p)) newPerms.push(p);
        });
        return newPerms;
      });
    }
  };

  const selectAllAll = (allPerms: string[]) => {
    const allSelected = allPerms.every(p => permissions.includes(p));
    if (allSelected) {
      setPermissions([]);
    } else {
      setPermissions(allPerms);
    }
  };

  const getCategoryIcon = (category: string) => {
    switch (category) {
      case "Parking Management": return <MapPin className="h-4 w-4" />;
      case "Booking Management": return <Calendar className="h-4 w-4" />;
      case "User Management": return <Users className="h-4 w-4" />;
      case "Customer Management": return <UserSquare className="h-4 w-4" />;
      case "Vehicle Management": return <Car className="h-4 w-4" />;
      case "Wallet & Transactions": return <Wallet className="h-4 w-4" />;
      case "Reviews & Ratings": return <Star className="h-4 w-4" />;
      case "Configuration Management": return <Settings className="h-4 w-4" />;
      case "Dashboard & Analytics": return <LayoutDashboard className="h-4 w-4" />;
      case "Financial Access": return <CreditCard className="h-4 w-4" />;
      case "System Settings & Security": return <Shield className="h-4 w-4" />;
      default: return <Target className="h-4 w-4" />;
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-white overflow-hidden flex flex-col">
      {/* Top Header */}
      <div className="flex items-center justify-between px-4 md:px-8 py-5 shrink-0 bg-white border-b shadow-sm z-20">
        <div>
          <h2 className="text-xl font-bold text-slate-900">
            {isNew ? "Create System User" : "Update User Account"}
          </h2>
          <p className="text-sm text-slate-500 font-medium mt-1">
            Manage staff access and permissions for the dashboard
          </p>
        </div>
        <Button
          variant="ghost"
          onClick={() => onOpenChange(false)}
          className="h-10 w-10 p-0 rounded-full hover:bg-primary hover:text-white text-slate-500 flex items-center justify-center border border-slate-200 shadow-sm transition-all"
        >
          <X className="h-5 w-5" />
        </Button>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-y-auto px-4 md:px-10 pb-6 bg-slate-50/30">
        <div className="max-w-7xl mx-auto h-full pt-10">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* Left Column: Profile & Basic Info */}
            <div className="lg:col-span-1 space-y-6">
              {/* Profile Photo */}
              <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
                <h3 className="text-lg font-black text-slate-900 mb-6 flex items-center gap-2">
                  <UserIcon className="h-5 w-5 text-primary" />
                  Profile Photo
                </h3>
                <div className="flex flex-col items-center gap-6">
                  <div className="h-48 w-48 rounded-full border-8 border-white shadow-2xl flex items-center justify-center bg-slate-200 overflow-hidden relative group cursor-pointer transition-transform hover:scale-105">
                    {preview ? (
                      <img
                        src={preview}
                        alt="Preview"
                        className="h-full w-full object-cover"
                      />
                    ) : (
                      <UserIcon className="h-20 w-20 text-slate-400" />
                    )}
                    <label
                      htmlFor="profileImage"
                      className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer"
                    >
                      <Upload className="h-10 w-10 text-white" />
                    </label>
                  </div>

                  <Label
                    htmlFor="profileImage"
                    className="cursor-pointer text-sm font-black text-primary hover:opacity-80 transition-all flex items-center gap-2 px-6 py-3 rounded-full border border-primary/20 bg-white shadow-sm"
                  >
                    <Upload className="h-4 w-4" /> Upload Photo
                  </Label>
                  <input
                    id="profileImage"
                    type="file"
                    accept="image/*"
                    className="hidden"
                    onChange={(e) =>
                      setProfileImage(e.target.files?.[0] || null)
                    }
                  />
                </div>
              </div>

              {/* Role Selection */}
              <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
                <h3 className="text-lg font-black text-slate-900 mb-6 flex items-center gap-2">
                  <Shield className="h-5 w-5 text-primary" />
                  System Role
                </h3>
                <div className="space-y-4">
                  <div className="space-y-3">
                    <Label className="text-sm font-black text-slate-900">
                      Access Level *
                    </Label>
                    <Select
                      value={role}
                      onValueChange={(val) => setRole(val as UserRole)}
                    >
                      <SelectTrigger className="h-14 w-full rounded-2xl border-slate-200 bg-white text-lg font-bold">
                        <SelectValue placeholder="Choose Role" />
                      </SelectTrigger>
                      <SelectContent className="rounded-2xl shadow-2xl border-slate-100">
                        <SelectItem
                          value={UserRole.SYSTEM_SUPER_ADMIN}
                          className="h-12 font-bold text-primary"
                        >
                          System Super Admin
                        </SelectItem>
                        <SelectItem
                          value={UserRole.SYSTEM_ADMIN}
                          className="h-12 font-bold"
                        >
                          System Admin
                        </SelectItem>
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-3">
                    <Label className="text-sm font-black text-slate-900">
                      Organization
                    </Label>
                    <div className="flex items-center gap-3 p-4 bg-slate-50 rounded-2xl border border-slate-100">
                      <Building2 className="h-5 w-5 text-slate-400" />
                      <span className="text-sm font-bold text-slate-600">PossibleTech</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Right Column: Contact Info & Permissions */}
            <div className="lg:col-span-2 space-y-6">
              {/* Contact Information */}
              <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
                <h3 className="text-lg font-black text-slate-900 mb-6">
                  Contact Information
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-3 md:col-span-2">
                    <Label className="text-sm font-black text-slate-900">
                      Full Name *
                    </Label>
                    <Input
                      className={`h-14 w-full rounded-2xl border-slate-200 bg-white text-lg font-bold px-4 focus:ring-2 focus:ring-primary/20 ${errors.fullName ? "border-red-500 bg-red-50" : ""}`}
                      placeholder="e.g. Samuel Ayele"
                      value={fullName}
                      onChange={(e) => {
                        setFullName(e.target.value);
                        if (errors.fullName) setErrors({ ...errors, fullName: "" });
                      }}
                    />
                    {errors.fullName && <p className="text-xs text-red-500 font-medium">{errors.fullName}</p>}
                  </div>

                  <div className="space-y-3">
                    <Label className="text-sm font-black text-slate-900 flex items-center gap-2">
                      <Mail className="h-4 w-4 text-primary" />
                      Email Address *
                    </Label>
                    <Input
                      className={`h-14 w-full rounded-2xl border-slate-200 bg-white text-lg font-bold px-4 focus:ring-2 focus:ring-primary/20 ${errors.email ? "border-red-500 bg-red-50" : ""}`}
                      type="email"
                      placeholder="samuel@parking-mgmt.com"
                      value={email}
                      onChange={(e) => {
                        setEmail(e.target.value);
                        if (errors.email) setErrors({ ...errors, email: "" });
                      }}
                    />
                    {errors.email && <p className="text-xs text-red-500 font-medium">{errors.email}</p>}
                  </div>

                  <div className="space-y-3">
                    <Label className="text-sm font-black text-slate-900 flex items-center gap-2">
                      <Phone className="h-4 w-4 text-primary" />
                      Phone Number *
                    </Label>
                    <Input
                      className={`h-14 w-full rounded-2xl border-slate-200 bg-white text-lg font-bold px-4 focus:ring-2 focus:ring-primary/20 ${errors.phoneNumber ? "border-red-500 bg-red-50" : ""}`}
                      placeholder="+251 9..."
                      value={phoneNumber}
                      onChange={(e) => {
                        setPhoneNumber(e.target.value);
                        if (errors.phoneNumber) setErrors({ ...errors, phoneNumber: "" });
                      }}
                    />
                    {errors.phoneNumber && <p className="text-xs text-red-500 font-medium">{errors.phoneNumber}</p>}
                  </div>
                </div>
              </div>

              {/* Permissions Section (Revamped) */}
              <div className="bg-white rounded-3xl border border-slate-200 shadow-xl overflow-hidden flex flex-col min-h-[600px]">
                {/* Header Section */}
                <div className="p-8 border-b bg-slate-50/50 space-y-6">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className="h-12 w-12 rounded-2xl bg-primary/10 flex items-center justify-center text-primary shadow-inner">
                        <Shield className="h-6 w-6" />
                      </div>
                      <div>
                        <h3 className="text-xl font-black text-slate-900 tracking-tight">Access Permissions</h3>
                        <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-0.5">Define granular system capabilities</p>
                      </div>
                    </div>
                    <div className="flex flex-col items-end gap-1">
                      <Badge className="bg-primary/10 text-primary border-none font-black text-xs px-3 py-1 rounded-full">
                        {permissions.length} PERMISSIONS ACTIVE
                      </Badge>
                      <button
                        onClick={() => {
                          const allContextPerms = Object.values(getPermissionsByContext(role === UserRole.PARKING_SUPER_ADMIN || role === UserRole.PARKING_MANAGER)).flat() as string[];
                          selectAllAll(allContextPerms);
                        }}
                        className="text-[10px] font-black text-slate-400 hover:text-primary uppercase tracking-widest transition-colors underline underline-offset-4"
                      >
                        {permissions.length === Object.values(getPermissionsByContext(role === UserRole.PARKING_SUPER_ADMIN || role === UserRole.PARKING_MANAGER)).flat().length ? "Deselect All" : "Select All Capabilities"}
                      </button>
                    </div>
                  </div>

                  {/* Search & Role Context */}
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="relative">
                      <SearchIcon className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
                      <Input
                        placeholder="Search specific permission..."
                        className="pl-12 h-12 rounded-2xl border-slate-200 bg-white focus:ring-primary/20 font-bold"
                        value={permSearch}
                        onChange={(e) => setPermSearch(e.target.value)}
                      />
                    </div>
                    <div className="bg-white border rounded-2xl p-3 flex items-center justify-between shadow-sm">
                      <div className="flex items-center gap-2">
                        <div className="w-2 h-2 rounded-full bg-blue-500 animate-pulse" />
                        <span className="text-[10px] font-black text-slate-600 uppercase tracking-widest">
                          {role.replace(/-/g, " ")} Context
                        </span>
                      </div>
                      <p className="text-[10px] text-slate-400 font-bold">
                        {role === UserRole.PARKING_SUPER_ADMIN || role === UserRole.PARKING_MANAGER
                          ? "Parking Site Scope"
                          : "Full Global System Scope"}
                      </p>
                    </div>
                  </div>
                </div>

                {/* Permissions List Grid */}
                <div className="p-8 overflow-y-auto h-[500px] custom-scrollbar bg-slate-50/20">
                  <div className="grid grid-cols-1 gap-6">
                    {Object.entries(
                      getPermissionsByContext(
                        role === UserRole.PARKING_SUPER_ADMIN || role === UserRole.PARKING_MANAGER
                      )
                    ).map(([category, categoryPermissions]) => {
                      const permArray = categoryPermissions as string[];

                      // Filter by search
                      const filteredPerms = permArray.filter(p =>
                        PERMISSION_LABELS[p].toLowerCase().includes(permSearch.toLowerCase()) ||
                        p.toLowerCase().includes(permSearch.toLowerCase())
                      );

                      if (permSearch && filteredPerms.length === 0) return null;

                      const allSelected = filteredPerms.length > 0 && filteredPerms.every(p => permissions.includes(p));
                      const someSelected = filteredPerms.some(p => permissions.includes(p));
                      const isExpanded = expandedCategories.includes(category) || permSearch.length > 0;

                      return (
                        <div key={category} className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm hover:shadow-md transition-all">
                          {/* Category Header */}
                          <div
                            className={cn(
                              "flex items-center justify-between p-5 cursor-pointer transition-colors select-none",
                              allSelected ? "bg-primary/5" : "bg-white"
                            )}
                            onClick={() => {
                              setExpandedCategories(prev =>
                                prev.includes(category) ? prev.filter(c => c !== category) : [...prev, category]
                              );
                            }}
                          >
                            <div className="flex items-center gap-4">
                              <div className={cn(
                                "h-10 w-10 rounded-xl flex items-center justify-center transition-all shadow-sm border",
                                allSelected ? "bg-primary text-white border-primary" : "bg-slate-50 text-slate-400 border-slate-100"
                              )}>
                                {allSelected ? <Check className="h-5 w-5 stroke-[3px]" /> : getCategoryIcon(category)}
                              </div>
                              <div>
                                <h4 className="font-black text-slate-900 leading-none">{category}</h4>
                                <p className="text-[10px] font-bold text-slate-400 mt-1 uppercase tracking-tighter">
                                  {permArray.filter(p => permissions.includes(p)).length} of {permArray.length} Selected
                                </p>
                              </div>
                            </div>

                            <div className="flex items-center gap-4">
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  toggleCategory(permArray);
                                }}
                                className={cn(
                                  "px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all",
                                  allSelected ? "bg-red-50 text-red-600 hover:bg-red-100" : "bg-primary/10 text-primary hover:bg-primary/20"
                                )}
                              >
                                {allSelected ? "Deselect Group" : "Select Group"}
                              </button>
                              <ChevronRight className={cn("h-4 w-4 text-slate-300 transition-transform", isExpanded && "rotate-90")} />
                            </div>
                          </div>

                          {/* Category Permissions List */}
                          <div className={cn(
                            "grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2 px-6 pb-6 bg-white overflow-hidden transition-all",
                            isExpanded ? "max-h-[1000px] pt-2" : "max-h-0"
                          )}>
                            {filteredPerms.map((permission: string) => {
                              const isChecked = permissions.includes(permission);
                              return (
                                <div
                                  key={permission}
                                  className={cn(
                                    "group flex items-center gap-3 p-3 rounded-xl border transition-all cursor-pointer",
                                    isChecked
                                      ? "bg-primary/5 border-primary/20 shadow-sm"
                                      : "bg-slate-50/50 border-transparent hover:bg-white hover:border-slate-200"
                                  )}
                                  onClick={() => togglePermission(permission)}
                                >
                                  <div className={cn(
                                    "h-5 w-5 rounded-md border-2 flex items-center justify-center transition-all shrink-0",
                                    isChecked ? "bg-primary border-primary" : "bg-white border-slate-200 group-hover:border-slate-400"
                                  )}>
                                    {isChecked && <Check className="h-3 w-3 text-white stroke-[4px]" />}
                                  </div>
                                  <span className={cn(
                                    "text-xs font-bold transition-colors truncate",
                                    isChecked ? "text-primary" : "text-slate-600"
                                  )}>
                                    {PERMISSION_LABELS[permission]}
                                  </span>
                                </div>
                              );
                            })}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>

                {/* Warning/Info Footer */}
                <div className="p-6 bg-slate-900 border-t flex items-center gap-4 shrink-0">
                  <div className="h-10 w-10 rounded-xl bg-white/10 flex items-center justify-center text-amber-400 shrink-0">
                    <Shield className="h-5 w-5" />
                  </div>
                  <div>
                    <p className="text-[10px] font-black text-white/90 uppercase tracking-[0.15em]">Security Protocol Notice</p>
                    <p className="text-[10px] text-white/50 font-bold leading-relaxed">
                      Changes to permissions take effect on the next user login. System Super Admins maintain absolute access regardless of selections.
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Footer Navigation */}
      <div className="border-t py-6 px-4 md:px-10 bg-white shrink-0 shadow-lg">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="text-sm text-slate-500 font-medium">
            {permissions.length > 0 && (
              <span className="text-primary font-bold">{permissions.length} permissions</span>
            )} selected
          </div>
          <div className="flex items-center gap-4">
            <Button
              variant="ghost"
              onClick={() => onOpenChange(false)}
              className="h-14 px-8 rounded-xl font-bold text-slate-400 hover:text-slate-900"
            >
              Cancel
            </Button>

            <Button
              onClick={handleSubmit}
              disabled={isLoading}
              className="h-14 px-16 rounded-xl bg-primary hover:opacity-90 text-white font-bold transition-all min-w-[160px] shadow-lg shadow-primary/10"
            >
              {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              {isNew ? "Create User" : "Update User"}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}
